-- ============================================================================
--  SAPI — seed data
--  Generated by server/scripts/generate-seed.mts — do not edit by hand.
--  Dataset "as of" Oct 11, 2026. Re-run `npm run seed:sql` after changing
--  anything under src/app/data/.
--
--  Run the migrations first:
--      0001_schema.sql -> 0002_rls.sql -> 0003_analytics.sql -> 0004_matchmaker.sql
--
--  This script runs as the postgres role, so Row Level Security is bypassed.
--  It is safe to run more than once: reference tables are upserted, while
--  transactional rows (stock, tickets, transfers, cycle tasks) are only
--  inserted when absent, so a clerk's in-progress work is never clobbered.
-- ============================================================================

begin;

-- ── branches ──────────────────────────────────────────────────────────────────
-- branches: 8 row(s)
on conflict (id) do update set name = excluded.name, short_name = excluded.short_name, region = excluded.region, manager = excluded.manager, address = excluded.address, phone = excluded.phone, is_main = excluded.is_main;

-- ── parts ─────────────────────────────────────────────────────────────────────
-- parts: 29 row(s)
on conflict (sku) do update set sku = excluded.sku, name = excluded.name, category = excluded.category, brand = excluded.brand, unit_cost = excluded.unit_cost, reorder_point = excluded.reorder_point, abc_class = excluded.abc_class;

-- ── suppliers ─────────────────────────────────────────────────────────────────
-- suppliers: 9 row(s)
on conflict (id) do update set name = excluded.name, categories = excluded.categories, phone = excluded.phone, email = excluded.email, lead_time_days = excluded.lead_time_days, rating = excluded.rating, active_pos = excluded.active_pos, status = excluded.status;

-- ── company_settings ──────────────────────────────────────────────────────────
-- company_settings: 1 row(s)
on conflict (id) do update set name = excluded.name, short_name = excluded.short_name, abbr = excluded.abbr, system_name = excluded.system_name, hq = excluded.hq, phone = excluded.phone, email = excluded.email, website = excluded.website, branch_count = excluded.branch_count, no_phone_policy = excluded.no_phone_policy;

-- ── stock_records ─────────────────────────────────────────────────────────────
-- stock_records: 232 row(s)
on conflict (sku, branch_id) do nothing;

on conflict (sku, branch_id) do nothing;

-- ── discrepancies ─────────────────────────────────────────────────────────────
-- discrepancies: 52 row(s)
on conflict (id) do nothing;

-- ── transfers ─────────────────────────────────────────────────────────────────
-- transfers: 26 row(s)
on conflict (id) do nothing;

-- ── purchase_orders ───────────────────────────────────────────────────────────
-- purchase_orders: 14 row(s)
on conflict (id) do nothing;

-- ── cycle_tasks ───────────────────────────────────────────────────────────────
-- cycle_tasks: 64 row(s)
on conflict (id) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
